INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (166, 274, 'Copy paper in jumbo roll size', '../upload/image/20181227/20181227113024_63541.jpg', '<p></p><p><span style="color:#009900;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><strong>Copy paper in jumbo rolls size</strong></span></p> <p><span style="color:#009900;font-size:18px;background-color:#FFFFFF;font-family:Tahoma;">We are one of the fewer factories who can offer only Copy paper jumbo roll products with GRM is from 48 GRM to 100GRM with outstanding quality . We import the raw mateiral(wooden pulp) from overseas like Russia and other area .Also we are one of the fewer factories who can offer only LWC paper products in quality actual 100% wooden pulp .</span></p> <p><span style="color:#009900;font-size:18px;background-color:#FFFFFF;font-family:Tahoma;">Roll size:</span></p> <p><span style="color:#E53333;font-size:18px;background-color:#FFFFFF;"><span style="font-family:Tahoma;font-size:18px;color:#009900;">Photocopy PAPER JUMBO ROLLS on a reel to be sheeted into A4 &amp; A3 ream sizes.</span></span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-size:22px;"><span style=''font-family:"font-size:22px;''> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Basis weight range: 70-75- 80 g/m2</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">The paper reel will be used on the following machine:</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Core: 76MM (3"), 152.4mm (6")</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Coil Max: 600mm -1,200mm</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Max Weight: 2000Kgs</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Max Width: 1500mm (For example: 840 1055MM...） </span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">------ Two types following :</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Economy type:</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- grammage: (80 +- 3) g/sm</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- caliper: (106 +- 4) mm/1000</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- stiffness L&amp;W:</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> MD min 100 mN</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> CD min 40 mN</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- roughness bendtsen: (200 +- 50) ml/min</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- CIE whiteness: 146 +- 3</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- brightness with UV: (103,5 +- 1,5) %</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- opacity: min 90 %.</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Allround type:</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- grammage: (80 +- 3) g/sm</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- caliper: (106 +- 3) mm/1000</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- stiffness L&amp;W:</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> MD min (125 +- 15) mN</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> CD min (60 +- 10) mN</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- roughness bendtsen: (200 +- 50) ml/min</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- CIE whiteness: 160 +- 3</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- brightness with UV: (110 +- 1,5) %</span><br/> </span><span style="color:#009900;font-family:Tahoma;font-size:18px;">- opacity: min 91 %.</span></span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <img alt="" src="../upload/image/20180826/20180826220101_80230.jpg"/><img alt="" src="../upload/image/20180826/20180826220101_37191.jpg"/><img alt="" src="../upload/image/20180826/20180826220101_63871.jpg"/><img alt="" src="../upload/image/20180826/20180826220101_71712.jpg"/><img alt="" src="../upload/image/20180826/20180826220101_37800.jpg"/><img alt="" src="../upload/image/20180826/20180826220102_85923.jpg"/><img alt="" src="../upload/image/20180826/20180826220102_41720.jpg"/><img alt="" src="../upload/image/20180826/20180826220102_10909.jpg"/><img alt="" src="../upload/image/20180826/20180826220102_47408.jpg"/><img alt="" src="../upload/image/20180826/20180826220102_79296.jpg"/><img alt="" src="../upload/image/20180826/20180826220103_43708.jpg"/><img alt="" src="../upload/image/20180826/20180826220103_92534.jpg"/></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (166, 426, 'Jumbo rolls Copy paper', '../upload/image/20211220/20211220132600_15520.jpg', '<p><h4> <span style="font-size:18px;font-family:Tahoma;color:#009900;">Jumbo rolls Copy paper<br/> </span><span style="font-size:18px;font-family:Tahoma;color:#009900;">Jumbo rolls Copy paper to be slited the&nbsp;</span><span style="font-size:18px;font-family:Tahoma;color:#009900;"><span style="font-size:18px;font-family:Tahoma;color:#009900;">A4 COPY PAPER finished size</span><br/> </span><span style="font-size:18px;font-family:Tahoma;color:#009900;">--- 70,75,80G COPY PAPERJUMBO ROLLS, 100% virgin wood pulp Jumbo rolls to slit A4 sizes sheets , whiteness:100%&nbsp;&nbsp;<br/> </span><span style="color:#009900;font-size:18px;font-family:Tahoma;">--- Jumbo roll paper roll width: 840-848,1055-1056mm....&nbsp;<br/> </span><span style="font-size:18px;font-family:Tahoma;color:#009900;">--- Roll outer diameter: within1200rnm,&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<br/> </span><span style="font-size:18px;font-family:Tahoma;color:#009900;">--- Inner Core:76mm or 152mm (usually we offer 3inch=76MM)&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<br/> </span><span style="font-size:18px;font-family:Tahoma;color:#009900;">--- Suit for the&nbsp;</span><span style="font-size:18px;font-family:Tahoma;color:#009900;">SHEETING &amp; WRAPPING MACHINE&nbsp;</span><span style="font-size:18px;font-family:Tahoma;color:#009900;">(speed)&nbsp;</span><span style="font-size:18px;font-family:Tahoma;color:#009900;">: 34—37 reams/min&nbsp;<br/> </span><span style="font-size:18px;font-family:Tahoma;color:#009900;">--- HS code: 4802620000&nbsp;</span> </h4></p>', '2026-09-06 20:58:45');